// Generated by philote from page /tasks/new. Do not edit.
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import { projects } from "@/lib/api";
import { must } from "@/lib/backend";

import { submit } from "./actions";
import Form from "./form";

export const metadata: Metadata = { title: "New Task" };

export default function Page() {
    return (
        <main className="flex-1 px-4 py-10">
            <div className="mx-auto max-w-xl space-y-6">
                <h1 className="font-heading text-3xl font-semibold tracking-tight">{"New Task"}</h1>
                <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                    <Loaded />
                </Suspense>
            </div>
        </main>
    );
}

// Loaded fills the form once its record and choices are in.
async function Loaded() {
    await connection();
    const options = {
        project_id: (await must(projects.list())).map((r) => ({ id: r.id, label: r.name })),
    };
    return <Form action={submit} initial={{}} options={options} />;
}
